// Render start command for the API (render.yaml). Runs from apps/api.
//
// 1. Reports what the managed database user may do (superuser, CREATEROLE, BYPASSRLS), so a
//    provider limit shows up plainly in the deploy log instead of as a confusing failure later.
// 2. Applies migrations with the owner connection (DATABASE_URL).
// 3. Gives the restricted fieldline_app role a login password (APP_DB_PASSWORD, generated by
//    Render) and derives APP_DATABASE_URL from DATABASE_URL. The API refuses to serve requests on
//    any role that bypasses Row-Level Security, so it must connect as fieldline_app.
// 4. Starts the built API (dist/main.js) with that environment.
import { spawn, spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import postgres from 'postgres';

const ownerUrl = process.env.DATABASE_URL;
const appPassword = process.env.APP_DB_PASSWORD;
if (!ownerUrl || !appPassword) {
  console.error('[render-start] DATABASE_URL and APP_DB_PASSWORD must be set.');
  process.exit(1);
}

const owner = postgres(ownerUrl, { max: 1, onnotice: () => {} });
try {
  const [me] = await owner`
    select current_user as user, rolsuper, rolcreaterole, rolbypassrls
    from pg_roles where rolname = current_user`;
  console.info(
    `[render-start] database user ${me.user}: superuser=${me.rolsuper} createrole=${me.rolcreaterole} bypassrls=${me.rolbypassrls}`,
  );
} finally {
  await owner.end();
}

// The built migrator starts in a fraction of the time tsx needs on a small instance, which
// matters every time a sleeping free service wakes up. tsx is the fallback for unbuilt checkouts.
const [migrateBin, migrateArgs] = existsSync('dist/migrate.js')
  ? ['node', ['dist/migrate.js']]
  : ['npx', ['tsx', 'src/db/migrate.ts']];
const migrate = spawnSync(migrateBin, migrateArgs, { stdio: 'inherit', env: process.env });
if (migrate.status !== 0) {
  console.error('[render-start] migrations failed; not starting the API.');
  process.exit(migrate.status ?? 1);
}

const admin = postgres(ownerUrl, { max: 1, onnotice: () => {} });
try {
  const literal = `'${appPassword.replace(/'/g, "''")}'`;
  await admin.unsafe(`ALTER ROLE fieldline_app LOGIN PASSWORD ${literal}`);
  console.info('[render-start] fieldline_app login enabled');
} catch (error) {
  console.error('[render-start] could not enable the fieldline_app login:', error.message);
  await admin.end();
  process.exit(1);
}
await admin.end();

const appUrl = new URL(ownerUrl);
appUrl.username = 'fieldline_app';
appUrl.password = appPassword;

const api = spawn('node', ['dist/main.js'], {
  stdio: 'inherit',
  env: { ...process.env, APP_DATABASE_URL: appUrl.toString() },
});
for (const signal of ['SIGTERM', 'SIGINT']) process.on(signal, () => api.kill(signal));
api.on('exit', (code) => process.exit(code ?? 0));
